import * as THREE from 'three';

import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import { ADDITION, SUBTRACTION, Brush, Evaluator } from 'three-bvh-csg';
import { Reflector } from 'three/examples/jsm/objects/Reflector.js';

import { WebGLRenderer } from 'three';
import { WebGPURenderer } from 'three/webgpu';

export const createRenderer = async (options: {
	canvas?: HTMLCanvasElement;
	antialias?: boolean;
	alpha?: boolean;
	performanceMode?: boolean;
	useWebGPU?: boolean;
}): Promise<WebGLRenderer | WebGPURenderer> => {
	const { canvas, antialias = true, alpha = false, performanceMode = false, useWebGPU = true } = options;

	const isWebGPUSupported = useWebGPU && navigator.gpu;

	if (isWebGPUSupported) {
		try {
			const renderer = new WebGPURenderer({ canvas, antialias, alpha });
			await renderer.init();
			console.log('WebGPU enabled');
			return renderer;
		} catch (err) {
			console.warn('WebGPU initialization failed, falling back to WebGL.');
		}
	}

	const renderer = new WebGLRenderer({
		canvas,
		antialias,
		alpha,
		powerPreference: 'high-performance',
		// stencil: true
	});
	console.log('WebGL enabled');
	return renderer;
};

export const getDeepCloneGroup = (original: THREE.Group): THREE.Group => {
	const clone = original.clone(true);
	clone.traverse((child) => {
		if ((child as THREE.Mesh).isMesh) {
			const mesh = child as THREE.Mesh;
			mesh.geometry = mesh.geometry.clone();

			if (Array.isArray(mesh.material)) {
				mesh.material = mesh.material.map((mat) => mat.clone());
			} else {
				mesh.material = mesh.material.clone();
			}
		}
	});
	return clone;
};
export const getUnionMeshFromMeshes = (meshes: THREE.Mesh[], material: THREE.Material): THREE.Mesh => {
	if (meshes.length === 0) throw new Error('No meshes provided');

	const baseBrush = new Brush(meshes[0].geometry, material);
	baseBrush.applyMatrix4(meshes[0].matrixWorld);
	baseBrush.updateMatrixWorld();

	const evaluator = new Evaluator();
	let resultBrush = baseBrush;

	for (let i = 1; i < meshes.length; i++) {
		const mesh = meshes[i];

		const brush = new Brush(mesh.geometry, material);
		brush.applyMatrix4(mesh.matrixWorld);
		brush.updateMatrixWorld();

		resultBrush = evaluator.evaluate(resultBrush, brush, ADDITION);
	}

	resultBrush.geometry.computeBoundingBox();
	resultBrush.geometry.computeBoundingSphere();

	resultBrush.geometry.computeVertexNormals();

	return new THREE.Mesh(resultBrush.geometry, material);
};
export const getSubtractionMesh = (a: THREE.BufferGeometry, b: THREE.BufferGeometry, material) => {
	const brush1 = new Brush(a, material);
	brush1.updateMatrixWorld();

	const brush2 = new Brush(b, material);
	brush2.updateMatrixWorld();

	const evaluator = new Evaluator();
	const resultMesh = evaluator.evaluate(brush1, brush2, SUBTRACTION);
	resultMesh.name = 'bvh-csg';
	return resultMesh;
};

export const getDirectionalLight = (x: number = 100, y: number = 100, z: number = 100, isPerformanceMode = false) => {
	const light = new THREE.DirectionalLight(0xffffff, 5);
	light.position.set(x, y, z);
	light.castShadow = true;
	light.shadow.bias = isPerformanceMode ? -0.001 : -0.0005;
	// light.shadow.bias = -0.00001;

	light.shadow.mapSize.width = 1024;
	light.shadow.mapSize.height = 1024;
	// light.shadow.mapSize.width = 2048 * 4;
	// light.shadow.mapSize.height = 2048 * 4;

	light.shadow.camera.near = 0.5;
	light.shadow.camera.far = 1000;
	light.shadow.camera.left = -100;
	light.shadow.camera.right = 100;
	light.shadow.camera.top = 100;
	light.shadow.camera.bottom = -100;
	return light;
};

export const createStudioEnvironment = () => {
	const geometry = new THREE.SphereGeometry(1000, 32, 16);

	const material = new THREE.ShaderMaterial({
		uniforms: {
			topColor: { value: new THREE.Color(0xffffff) },
			bottomColor: { value: new THREE.Color(0xf2f2f2) },
			offset: { value: 1.4 },
			exponent: { value: 1.4 },
		},
		vertexShader: /* glsl */ `
			varying vec3 vWorldPosition;
			void main() {
				vec4 worldPosition = modelMatrix * vec4(position, 1.0);
				vWorldPosition = worldPosition.xyz;
				gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
			}
		`,
		fragmentShader: /* glsl */ `
			uniform vec3 topColor;
			uniform vec3 bottomColor;
			uniform float offset;
			uniform float exponent;
			varying vec3 vWorldPosition;

			void main() {
				float h = normalize(vWorldPosition + vec3(0.0, offset, 0.0)).y;
				float factor = max(pow(max(h, 0.0), exponent), 0.0);
				vec3 color = mix(bottomColor, topColor, factor);
				gl_FragColor = vec4(color, 1.0);
			}
		`,
		side: THREE.BackSide,
		toneMapped: false,
	});

	return new THREE.Mesh(geometry, material);
};

export const getGroundBasic = (ground: number = 0, zUp = false) => {
	const planeGeometry = new THREE.PlaneGeometry(1500, 1500);
	const planeMaterial = new THREE.MeshStandardMaterial({
		color: 0xededed,
		// color: 0xcecece,
		// color: 0xb4a4a4,
		// roughness: 0.0,
		// metalness: 0.8,
	});

	const planeGround = new THREE.Mesh(planeGeometry, planeMaterial);
	planeGround.receiveShadow = true;
	if (zUp) {
		planeGround.position.z = ground;
	} else {
		planeGround.position.y = ground;
		planeGround.rotation.x = -Math.PI * 0.5;
	}
	planeGround.name = 'ground';
	return planeGround;
};

export const getGround = (scene, renderer) => {
	const groundReflector = new Reflector(new THREE.PlaneGeometry(500, 500), {
		clipBias: 0.03,
		textureWidth: window.innerWidth * window.devicePixelRatio,
		textureHeight: window.innerHeight * window.devicePixelRatio,
		color: 0xcecece,
	});
	// groundReflector.rotation.x = -Math.PI / 2;
	groundReflector.position.z = -18;
	return groundReflector;
};

export const extractIndependentMeshesFromFBX = (root: THREE.Object3D): THREE.Mesh[] => {
	const independentMeshes: THREE.Mesh[] = [];

	root.traverse((child) => {
		if (child instanceof THREE.Mesh) {
			child.updateMatrixWorld(true);

			const geometry = child.geometry.clone();
			const material = Array.isArray(child.material) ? child.material.map((mat) => mat.clone()) : child.material.clone();

			const newMesh = new THREE.Mesh(geometry, material);
			newMesh.applyMatrix4(child.matrixWorld);
			newMesh.name = child.name;

			independentMeshes.push(newMesh);
		}
	});

	return independentMeshes;
};

export const applyBoxUV = (geometry: THREE.BufferGeometry) => {
	geometry.computeBoundingBox();
	geometry.computeVertexNormals();

	const position = geometry.attributes.position;
	const normal = geometry.attributes.normal;
	const uvArray: number[] = [];

	const bbox = geometry.boundingBox!;
	const size = new THREE.Vector3();
	bbox.getSize(size);

	for (let i = 0; i < position.count; i++) {
		const nx = normal.getX(i);
		const ny = normal.getY(i);
		const nz = normal.getZ(i);

		const px = position.getX(i);
		const py = position.getY(i);
		const pz = position.getZ(i);

		let u = 0,
			v = 0;

		if (Math.abs(nx) > Math.abs(ny) && Math.abs(nx) > Math.abs(nz)) {
			u = (pz - bbox.min.z) / size.z;
			v = (py - bbox.min.y) / size.y;
		} else if (Math.abs(ny) > Math.abs(nz)) {
			u = (px - bbox.min.x) / size.x;
			v = (pz - bbox.min.z) / size.z;
		} else {
			u = (px - bbox.min.x) / size.x;
			v = (py - bbox.min.y) / size.y;
		}
		uvArray.push(u, v);
	}

	const uvAttr = new THREE.Float32BufferAttribute(uvArray, 2);
	geometry.setAttribute('uv', uvAttr);
};

export const detachAndApplyWorldTransform = (mesh: THREE.Mesh): THREE.Mesh => {
	mesh.updateMatrixWorld(true);

	const geometry = mesh.geometry.clone();
	const material = Array.isArray(mesh.material) ? mesh.material.map((mat) => mat.clone()) : mesh.material.clone();

	const newMesh = new THREE.Mesh(geometry, material);

	const worldMatrix = mesh.matrixWorld.clone();
	newMesh.applyMatrix4(worldMatrix);

	return newMesh;
};

export const isMesh = (obj: THREE.Object3D): obj is THREE.Mesh => {
	return (obj as any).isMesh === true;
};

export const isWebGLRenderer = (renderer: any): renderer is THREE.WebGLRenderer => {
	return renderer?.isWebGLRenderer === true;
};

export const isTexture = (obj: any): obj is THREE.Texture => {
	return obj && typeof obj === 'object' && obj.isTexture === true;
};

export const loadFBX = (pathFile: string, scale: number = 1, isWebGPU: boolean, performanceMode: boolean = false, clipingPlanes = [], zUp = false): Promise<THREE.Group> => {
	const scaleFactor = scale;
	const usePhysicalMaterial = !performanceMode && !isWebGPU;
	const loader = new FBXLoader();

	return new Promise((resolve, reject) => {
		loader.load(
			pathFile,
			(fbx) => {
				fbx.castShadow = true;
				fbx.receiveShadow = true;

				if (zUp) {
					fbx.rotation.x = Math.PI / 2;
				}

				fbx.traverse((child: THREE.Object3D) => {
					if (isMesh(child)) {
						child.castShadow = true;
						child.receiveShadow = true;

						const material = child.material;

						if (Array.isArray(material)) {
							child.material = material.map((mat) => {
								if (isWebGPU) {
									return new THREE.MeshStandardMaterial({
										map: mat.map ?? undefined,
										color: mat.color ?? new THREE.Color(0xffffff),
										normalMap: mat.normalMap ?? undefined,
										roughness: 0.7,
										metalness: 0.1,
										clippingPlanes: clipingPlanes,
									});
								} else if (performanceMode) {
									return new THREE.MeshStandardMaterial({
										map: mat.map ?? undefined,
										color: mat.color ?? new THREE.Color(0xffffff),
										normalMap: undefined,
										roughness: 0.7,
										metalness: 0.1,
										clippingPlanes: clipingPlanes,
									});
								} else {
									return new THREE.MeshPhysicalMaterial({
										map: mat.map ?? undefined,
										color: mat.color ?? new THREE.Color(0xffffff),
										normalMap: mat.normalMap ?? undefined,
										roughness: 0.7,
										metalness: 0.1,
										clippingPlanes: clipingPlanes,
									});
								}
							});
						} else {
							if (isWebGPU) {
								child.material = new THREE.MeshStandardMaterial({
									map: material.map ?? null,
									color: material.color ?? new THREE.Color(0xffffff),
									normalMap: material.normalMap ?? null,
									roughness: 0.6,
									metalness: 0.2,
									clippingPlanes: clipingPlanes,
								});
							} else if (performanceMode) {
								child.material = new THREE.MeshStandardMaterial({
									map: material.map ?? null,
									color: material.color ?? new THREE.Color(0xffffff),
									roughness: 0.6,
									metalness: 0.2,
									clippingPlanes: clipingPlanes,
								});
							} else {
								child.material = new THREE.MeshPhysicalMaterial({
									map: material.map ?? null,
									color: material.color ?? new THREE.Color(0xffffff),
									normalMap: material.normalMap ?? null,
									roughness: 0.6,
									metalness: 0.2,
									clippingPlanes: clipingPlanes,
								});
							}
						}
					}
				});

				fbx.scale.set(scaleFactor, scaleFactor, scaleFactor);
				fbx.updateMatrixWorld(true);
				resolve(fbx);
			},
			undefined,
			(error) => {
				reject(error);
			}
		);
	});
};
