import * as THREE from 'three';

import { ShaderMaterial, Mesh, BoxGeometry, Vector3 } from 'three';

import { SceneWrapper } from '../';

export class Playground {
	sceneWrapper: SceneWrapper;
	mesh: THREE.Mesh | null = null;
	geometry: THREE.BoxGeometry;
	originalPositions: Float32Array;
	elapsedTime: number = 0;

	doorWidth: number = 10;
	doorHeight: number = 20;
	doorDepth: number = 0.3;
	doorHeightSegments: number = 200;

	rollStartAbsoluteY: number = 5.0;

	rollLength: number = 5.0;
	rollRadius: number = 0.15;

	cubeMesh;

	clippingPlane: THREE.Plane;
	clippingPlane2: THREE.Plane;

	t = 0.0;

	sectionMesh;

	constructor(sceneWrapper: SceneWrapper) {
		this.sceneWrapper = sceneWrapper;
	}

	public init() {
		this.geometry = new THREE.BoxGeometry(
			this.doorWidth,
			this.doorHeight,
			this.doorDepth,
			1, // X segments
			this.doorHeightSegments, // Y segments
			1 // Z segments
		);

		this.originalPositions = new Float32Array(this.geometry.attributes.position.array);

		const material = new THREE.MeshStandardMaterial({
			color: 0x336699,
			side: THREE.DoubleSide,
		});
		this.mesh = new THREE.Mesh(this.geometry, material);
		this.sceneWrapper.scene.add(this.mesh);

		this.mesh.position.y = -100;

		const geometry = new THREE.BoxGeometry(10, 10, 10);
		this.clippingPlane = new THREE.Plane(new THREE.Vector3(0, -1, 0), 0);
		this.clippingPlane2 = new THREE.Plane(new THREE.Vector3(-1, 0, 0), 0);

		// 		const clippingPlane = new Vector3(0, 1, 0);
		// 		const clipOffset = 0.0;
		// 		const material2 = new ShaderMaterial({
		// 			vertexShader: `
		//     varying vec3 vPos;
		//     void main() {
		//       vPos = position;
		//       gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
		//     }
		//   `,
		// 			fragmentShader: `
		//     varying vec3 vPos;
		//     void main() {
		//       if (dot(vec3(0.0, 1.0, 0.0), vPos) < 0.0) discard;
		//       gl_FragColor = vec4(0.0, 1.0, 0.0, 1.0);
		//     }
		//   `,
		// 		});

		const material2 = new THREE.MeshStandardMaterial({
			color: 0x00ff00,
			clippingPlanes: [this.clippingPlane, this.clippingPlane2], // local clipping
			side: THREE.DoubleSide,
		});

		const cube = new THREE.Mesh(geometry, material2);
		this.sceneWrapper.scene.add(cube);

		this.cubeMesh = cube;

		const sectionMaterial = new THREE.MeshStandardMaterial({
			color: 0x000000,
			side: THREE.DoubleSide,
		});
		const sectionPlane = new THREE.PlaneGeometry(2, 2);
		const sectionMesh = new THREE.Mesh(sectionPlane, sectionMaterial);

		const planeNormal = this.clippingPlane.normal.clone();
		const planeConstant = this.clippingPlane.constant;
		sectionMesh.position.copy(planeNormal.clone().multiplyScalar(-planeConstant));

		const target = new THREE.Vector3().addVectors(sectionMesh.position, planeNormal);
		sectionMesh.lookAt(target);

		sectionMesh.position.add(planeNormal.clone().multiplyScalar(0.001));

		this.sceneWrapper.scene.add(sectionMesh);

		this.sectionMesh = sectionMesh;
	}

	public update(delta = 0.016) {
		if (!this.clippingPlane) return;
		this.cubeMesh.rotation.y += 0.001;

		const val = Math.sin(this.t);
		// console.log({ val });

		if (this.clippingPlane) {
			this.clippingPlane.constant += val;
			this.clippingPlane2.constant += val;

			const planeNormal = this.clippingPlane.normal.clone();
			const planeConstant = this.clippingPlane.constant;
			this.sectionMesh.position.copy(planeNormal.clone().multiplyScalar(-planeConstant));

			const target = new THREE.Vector3().addVectors(this.sectionMesh.position, planeNormal);
			this.sectionMesh.lookAt(target);

			this.sectionMesh.position.add(planeNormal.clone().multiplyScalar(0.001));
		}

		if (!this.mesh || !this.geometry) return;

		this.elapsedTime += delta;

		const minDoorBottomY = 0;
		const maxDoorBottomY = 15;
		const movementRange = (maxDoorBottomY - minDoorBottomY) / 2;
		const movementCenter = minDoorBottomY + movementRange;
		const movementSpeed = 0.5;

		this.mesh.position.y = movementCenter + movementRange * Math.sin(this.elapsedTime * movementSpeed) + this.doorHeight / 2;

		const positionAttribute = this.geometry.attributes.position;

		for (let i = 0; i < positionAttribute.count; i++) {
			const ox = this.originalPositions[i * 3 + 0];
			const oy = this.originalPositions[i * 3 + 1];
			const oz = this.originalPositions[i * 3 + 2];

			let transformedX = ox;
			let transformedY = oy;
			let transformedZ = oz;

			const currentVertexWorldY = this.mesh.position.y + oy;

			if (currentVertexWorldY > this.rollStartAbsoluteY) {
				const distanceAboveThreshold = currentVertexWorldY - this.rollStartAbsoluteY;
				const rollProgress = Math.min(1.0, distanceAboveThreshold / this.rollLength);

				const angle = rollProgress * Math.PI * 2;

				const localRollBaseY = this.rollStartAbsoluteY - this.mesh.position.y;

				transformedY = localRollBaseY + this.rollRadius * Math.sin(angle);

				transformedZ = -this.rollRadius * (1.0 - Math.cos(angle)) + oz;

				transformedX = ox;
			}

			positionAttribute.setXYZ(i, transformedX, transformedY, transformedZ);
		}

		positionAttribute.needsUpdate = true;
		this.geometry.computeVertexNormals();

		this.t += 0.01;
	}
}
