import * as THREE from 'three';
import { SceneWrapper } from '..';
export abstract class MeshWrapperCommon {
	public sceneWrapper: SceneWrapper;
	// public mesh: THREE.Mesh;
	public ready: boolean = false;
	constructor(sceneWrapper: SceneWrapper) {
		this.sceneWrapper = sceneWrapper;
		this.add();
	}
	public abstract init();
	public abstract show(value: boolean);
	public add(): void {
		this.sceneWrapper.add(this);
	}
	public update() {
		return false;
	}
	public destroy() {
		// TODO
	}
}
