import { AppCore } from '..';

import { NSolarRobust, LocationTimeUtility, executingAutoSunDirectionTimer } from '../../utils/NSolarRobustDistill';

import { APIHypercube } from './api';

import config from '../../config';

export class AppCommon {
	public appCore: AppCore;
	public api: APIHypercube;

	public solar: NSolarRobust;

	private _showEnv = true;
	private _sampleCameraPositionIndex = 0;
	private _sampleCameraPosition = config.sampleCameraPosition;
	private _sampleCameraTargetPosition = config.sampleCameraTargetPosition;

	private _sampleHDRIIndex = -1;
	private _sampleHDRI = config.HDRI;

	private autoSunDirectionTimerDestroy: () => void;

	constructor(appCore: AppCore) {
		this.appCore = appCore;
		if (this.appCore.isPerformanceMode) {
			this._sampleHDRI = config.HDRI_SMALL;
		}
		this.api = new APIHypercube(this);

		this.solar = new NSolarRobust();

		this.init();
	}
	public async init() {
		if (config.autoTimezone) {
			this.updateSolarVec();
			this.autoSunDirectionTimerDestroy = executingAutoSunDirectionTimer(this.updateSolarVec);
		}
	}
	public updateLogParameters() {
		if (this.appCore.solution.view) {
			this.appCore.solution.view.metadataPosition.textContent = `Width: ${this.appCore.sceneWrapper.configurator.dimension.width}, Length: ${this.appCore.sceneWrapper.configurator.dimension.length}, Height: ${this.appCore.sceneWrapper.configurator.dimension.height}, Thickness: ${this.appCore.sceneWrapper.configurator.dimension.thickness}, Camera Radius: ${this.appCore.sceneWrapper.configurator.dimension.radiusCamera}`;
		}
	}
	public setWidthParametricHC(value: number) {
		this.appCore.sceneWrapper.configurator.hypercubeSkin?.exoSkeletonMeshes.setWidth(value);
		this.updateLogParameters();
		this.renderForce();
	}
	public setLengthParametricHC(value: number) {
		this.appCore.sceneWrapper.configurator.hypercubeSkin?.exoSkeletonMeshes.setLength(value);
		this.updateLogParameters();
		this.renderForce();
	}
	public setHeightParametricHC(value: number) {
		this.appCore.sceneWrapper.configurator.hypercubeSkin?.exoSkeletonMeshes.setHeight(value);
		this.updateLogParameters();
		this.renderForce();
	}
	public setSizeSkeletonParametricHC(value: number) {
		this.appCore.sceneWrapper.configurator.hypercubeSkin?.exoSkeletonMeshes.setThickness(value);
		this.updateLogParameters();
		this.renderForce();
	}
	public setSizeCameraHC(value: number) {
		this.appCore.sceneWrapper.configurator.hypercubeSkin?.exoSkeletonMeshes.setCameraSize(value);
		this.updateLogParameters();
		this.renderForce();
	}
	public toggleXrayParametricModel(value: boolean) {
		this.appCore.sceneWrapper.configurator.toggleXrayParametricModel(value);
		this.renderForce();
	}
	public setClippingYParametricHC(value: number) {
		this.appCore.sceneWrapper.materials.updateYClipping(value);
		this.renderForce();
	}
	public setClippingXParametricHC(value: number) {
		this.appCore.sceneWrapper.materials.updateXClipping(value);
		this.renderForce();
	}
	public setClippingZParametricHC(value: number) {
		this.appCore.sceneWrapper.materials.updateZClipping(value);
		this.renderForce();
	}
	public updateSolarVec = () => {
		const scale = 2;

		const result = LocationTimeUtility.getTimeFromCoordinatesIntl(37.5665, 126.978);

		this.solar.update(result.latitude, result.longitude, result.year, result.month, result.day, result.hour, result.minute);

		this.appCore.rendererCore.updateSolarVec(this.solar.VectorSun.x * scale, this.solar.VectorSun.y * scale, this.solar.VectorSun.z * scale);
		if (this.appCore.solution.view) {
			this.appCore.solution.view.metadataPosition.textContent = `Latitude: ${this.solar.latitude}, Day: ${this.solar.day}, Hour: ${this.solar.hour}, Min: ${this.solar.minute}`;
		}
		this.renderForce();
	};
	public get showEnv() {
		return this._showEnv;
	}
	public set showEnv(v: boolean) {
		this._showEnv = v;
	}
	public get runningDroneDevices() {
		return this.appCore.sceneWrapper.hyperCube?.runningDroneDevices;
	}
	public renderForce() {
		this.appCore.rendererCore.renderForce();
	}
	public set runningDroneDevices(v: boolean) {
		this.renderForce();
		if (this.appCore.sceneWrapper.hyperCube) {
			this.appCore.sceneWrapper.hyperCube.runningDroneDevices = v;
		}
	}
	// ......................... controlling scene
	public hideAll() {
		this.appCore.sceneWrapper.hideAll();
		this.renderForce();
	}
	public showHypercube() {
		this.appCore.sceneWrapper?.hyperCube.show(true);
		this.renderForce();
	}
	public hideHypercubeStatic() {
		this.appCore.sceneWrapper?.hyperCube.show(false);
		this.renderForce();
	}
	public showHypercubeStatic() {
		this.showHypercube();
	}
	public toggleScene() {
		this.appCore.sceneWrapper.activateGlobe = !this.appCore.sceneWrapper.activateGlobe;
		this._sampleCameraPositionIndex = 0;
		if (this.appCore.sceneWrapper.activateGlobe) {
			this.appCore.sceneWrapper.showGlobe();
		} else {
			this.appCore.sceneWrapper.showStudioEnv();
		}
		this.appCore.rendererCore.cameraStaring();
		this.renderForce();
	}
	public showStudioEnv() {
		this.appCore.sceneWrapper.hideAll();
		if (this.appCore.sceneWrapper.studioEnv) {
			this.appCore.sceneWrapper.studioEnv.show(!this.appCore.sceneWrapper.studioEnv.meshFloor.visible);
			this.appCore.sceneWrapper.hyperCube?.show(!this.appCore.sceneWrapper.hyperCube?.visible);
		}
		this.renderForce();
	}
	public showSubstation() {
		this.appCore.sceneWrapper.hideAll();
		if (this.appCore.sceneWrapper.substation) {
			this.appCore.sceneWrapper.hyperCube?.show(true);
			this.appCore.sceneWrapper.substation.showSubstation();
		}
		this.renderForce();
	}
	public showSubstationDiorama() {
		this.appCore.sceneWrapper.hideAll();
		if (this.appCore.sceneWrapper.substation) {
			this.appCore.sceneWrapper.hyperCube?.show(true);
			this.appCore.sceneWrapper.substation.showSubstationDiorama();
		}
		this.renderForce();
	}
	// ......................... end controlling scene
	public angleSolarPanel(v) {
		this.renderForce();

		if (this.appCore.sceneWrapper.hyperCube) {
			this.appCore.sceneWrapper.hyperCube.angleSolarPanel = v;
		}
	}
	// ....................................... start view changing
	public viewChangingForward() {
		this.changeCameraByOffset(1);
	}

	public viewChangingBackward() {
		this.changeCameraByOffset(-1);
	}
	private changeCameraByOffset(offset: number) {
		this._sampleCameraPositionIndex = (this._sampleCameraPositionIndex + offset + this._sampleCameraPosition.length) % this._sampleCameraPosition.length;
		this.viewChanging(this._sampleCameraPositionIndex);
		this.renderForce();
	}
	// ....................................... end view changing
	public viewChanging(index: number) {
		const scale = 1;

		const vec = this._sampleCameraPosition[index];

		this.appCore.rendererCore.cameraWrapper.duration = vec[3] !== undefined ? vec[3] : 1500;
		this.appCore.rendererCore.cameraWrapper.moveCamera(vec[0] * scale, vec[1] * scale, vec[2] * scale);

		const vecT = this._sampleCameraTargetPosition[index];
		this.appCore.rendererCore.cameraWrapper.moveTarget(vecT[0] * scale, vecT[1] * scale, vecT[2] * scale);
	}
	public changeFOV(value: number) {
		this.appCore.rendererCore.cameraWrapper.changeFOV = value;
		this.renderForce();
	}
	public decompose() {
		this.appCore.sceneWrapper.hyperCube?.decompose();
		this.renderForce();
	}
	public printCameraInfo() {
		this.appCore.rendererCore.cameraWrapper.log();
	}
	public hdriChanging() {
		const val = this._sampleHDRI[this._sampleHDRIIndex++ % this._sampleHDRI.length];
		this.appCore.rendererCore.updateHDRI(val);
		this.renderForce();
	}

	public toggleHDRIBackground(toggle: boolean) {
		this.appCore.rendererCore.toggleHDRIBackground(toggle);
		this.renderForce();
	}
	public toggleEffect(value: boolean | undefined = undefined) {
		this.appCore.rendererCore.toggleEffect(value);
		this.renderForce();
	}
	public toggleAdaptiveRendering() {
		this.appCore.rendererCore.toggleAdaptiveRendering();
	}
	public toggleShadow() {
		this.appCore.sceneWrapper.toggleShadow();
		this.renderForce();
	}
	public getSubstationVisibility() {
		this.renderForce();
		if (this.appCore.sceneWrapper.substation) {
			return this.appCore.sceneWrapper.substation.visibility;
		}
		return false;
	}
	public getSunVec(Latitude: number, Longitude: number, theDay: number, Hour: number) {
		const scale = 2;

		this.solar.update(Latitude, Longitude, this.solar.year, this.solar.month, theDay, Hour);

		this.appCore.rendererCore.updateSolarVec(this.solar.VectorSun.x * scale, this.solar.VectorSun.y * scale, this.solar.VectorSun.z * scale);

		if (this.appCore.solution.view) {
			this.appCore.solution.view.metadataPosition.textContent = `Latitude: ${this.solar.latitude}, Day: ${this.solar.day}, Hour: ${this.solar.hour}`;
		}
		this.renderForce();
	}
	public debuggerX(value: number) {
		// console.log("x: ", value);
		if (this.appCore.activeCommand.selectedMesh) {
			this.appCore.activeCommand.selectedMesh.position.x = value;
		}
		this.renderForce();
	}
	public debuggerY(value: number) {
		// console.log("y: ", value);
		if (this.appCore.activeCommand.selectedMesh) {
			this.appCore.activeCommand.selectedMesh.position.z = value;
		}
		this.renderForce();
	}
	public debuggerZ(value: number) {
		// console.log("z: ", value);
		if (this.appCore.activeCommand.selectedMesh) {
			this.appCore.activeCommand.selectedMesh.position.y = value;
		}
		this.renderForce();
	}
	public toggleAnimationRotatingA() {
		this.appCore.rendererCore.toggleAnimationRotatingA();
		this.renderForce();
	}
	public toggleAnimationRotatingB() {
		this.appCore.rendererCore.toggleAnimationRotatingB();
		this.renderForce();
	}
	// .... debug
	public roughness(value: number) {
		console.log('debuggerA:', value);

		if (this.appCore.activeCommand.selectedMesh) {
			console.log(this.appCore.activeCommand.selectedMesh.material);

			if (Array.isArray(this.appCore.activeCommand.selectedMesh.material)) {
				for (let i = 0; i < this.appCore.activeCommand.selectedMesh.material.length; ++i) {
					const mat = this.appCore.activeCommand.selectedMesh.material[i];
					console.log(mat);
					mat.roughness = value;
				}
			} else {
				this.appCore.activeCommand.selectedMesh.material.roughness = value;
			}
		}
		this.renderForce();
		// this.appCore.threeCore.togglePostProcessing();
	}

	public metalness(value: number) {
		console.log('metalness:', value);
		if (this.appCore.activeCommand.selectedMesh) {
			console.log(this.appCore.activeCommand.selectedMesh.material);

			if (Array.isArray(this.appCore.activeCommand.selectedMesh.material)) {
				for (let i = 0; i < this.appCore.activeCommand.selectedMesh.material.length; ++i) {
					const mat = this.appCore.activeCommand.selectedMesh.material[i];
					console.log(mat);
					mat.metalness = value;
				}
			} else {
				this.appCore.activeCommand.selectedMesh.material.metalness = value;
			}
		}
		this.renderForce();
	}
	public debuggerC(value: number) {
		console.log('debuggerC:', value);
		if (this.appCore.activeCommand.selectedMesh) {
			console.log(this.appCore.activeCommand.selectedMesh.material);

			if (Array.isArray(this.appCore.activeCommand.selectedMesh.material)) {
				for (let i = 0; i < this.appCore.activeCommand.selectedMesh.material.length; ++i) {
					const mat = this.appCore.activeCommand.selectedMesh.material[i];
					console.log(mat);
					mat.clearcoatRoughness = value;
				}
			} else {
				this.appCore.activeCommand.selectedMesh.material.clearcoatRoughness = value;
			}
		}

		this.appCore.sceneWrapper.hyperCube?.updateClipingPlane(value);

		this.appCore.sceneWrapper.configurator.updateClipping(value);

		this.renderForce();
	}
	public destroy() {
		if (this.autoSunDirectionTimerDestroy) this.autoSunDirectionTimerDestroy();
	}
}
